class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + date : date
}

class Car {
  + vehicleNumber : int
}

class Driver {
  + name : string
}

class CardReader {
  + verify(cardNumber : int) : boolean
}

class Barrier {
  + rise() : void
}

class Sign {
  + status : string
}

class Reception {
}

class CarPark {
}

Employee "1" -- "1" IdentityCard : wears
IdentityCard "1" -- "0..1" Car : used by
GuestCard "0..*" -- "0..1" Car : used by
Driver "1" -- "1" Car : drives
Car "1" -- "1" Barrier : triggers
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "1" Sign : displays
CarPark "1" -- "1" Barrier : has
CarPark "1" -- "1" Barrier : has
CarPark "1" -- "1" CardReader : has
Reception "1" -- "*" GuestCard : collects
@enduml

